"use client";

import * as React from "react";
import { Slider as SliderPrimitive } from "@base-ui/react/slider";

import { cn } from "@/lib/utils";
import { oxFace, oxHairline, slotWell } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Margin Slider: a thin grey slot behind a hairline. The filled part wears
 * the primary Button's oxblood face, and each knob is the small white knob of
 * the Switch with an oxblood edge. Pass an array value for a range.
 */
const Slider = React.forwardRef<HTMLDivElement, WithClassName<SliderPrimitive.Root.Props>>(
  ({ className, defaultValue, value, min = 0, max = 100, ...props }, ref) => {
    const _values = Array.isArray(value)
      ? value
      : Array.isArray(defaultValue)
        ? defaultValue
        : [min];

    return (
      <SliderPrimitive.Root
        data-slot="slider"
        ref={ref}
        thumbAlignment="edge"
        defaultValue={defaultValue}
        value={value}
        min={min}
        max={max}
        className={cn(
          "relative w-full data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
          className,
        )}
        {...props}
      >
        <SliderPrimitive.Control className="relative flex h-5 w-full touch-none select-none items-center">
          <SliderPrimitive.Track
            data-slot="slider-track"
            className={cn("relative h-1.5 w-full grow overflow-hidden rounded-full", slotWell)}
          >
            <SliderPrimitive.Indicator
              data-slot="slider-range"
              className={cn("rounded-full", oxFace)}
            />
          </SliderPrimitive.Track>
          {Array.from({ length: _values.length }, (_, index) => (
            <SliderPrimitive.Thumb
              data-slot="slider-thumb"
              key={index}
              className={cn(
                "block size-4 shrink-0 cursor-grab rounded-full bg-primary-foreground",
                oxHairline,
                "transition-transform duration-fast ease-(--ease-out) active:scale-110 active:cursor-grabbing motion-reduce:active:scale-100",
                "has-[:focus-visible]:ring-3 has-[:focus-visible]:ring-ring",
                "data-[disabled]:pointer-events-none",
              )}
            />
          ))}
        </SliderPrimitive.Control>
      </SliderPrimitive.Root>
    );
  },
);
Slider.displayName = "Slider";

export { Slider };
